"""Textual format of the CSS generated by easings."""

import re
from typing import Literal

import pytest
from svgblock import CubicBezier, Easing, Steps

from .shared import CURVES, CUBIC_BEZIERS, PRESETS, each

PlainNumber = r"-?\d+(?:\.\d+)?"
CUBIC_BEZIER_FORMAT = re.compile(
    rf"cubic-bezier\({PlainNumber}, {PlainNumber}, {PlainNumber}, "
    rf"{PlainNumber}\)")
NEGATIVE_ZERO = re.compile(r"-0(?![.\d])")
LINEAR_POINT = re.compile(r"-?\d+(?:\.\d{1,4})?")
MIN_LINEAR_POINTS = 32
MAX_LINEAR_POINTS = 200

Jump = Literal["start", "end", "none", "both"]


def linear_points(css: str) -> list[str]:
    """Split the text of a ``linear()`` function into its points.

    Parameters
    ----------
    css : str
        Text produced by ``Easing.css()`` of a curve.

    Returns
    -------
    list[str]
        The textual points, in order.
    """
    assert css.startswith("linear(") and css.endswith(")")
    return css[len("linear("):-1].split(", ")


@each({**PRESETS, **CUBIC_BEZIERS})
def test_cubic_bezier_uses_plain_decimal_notation(easing: Easing) -> None:
    """Numbers are written in plain decimals, never in scientific notation."""
    assert CUBIC_BEZIER_FORMAT.fullmatch(easing.css())


@pytest.mark.parametrize(
    ("easing", "expected"),
    [
        (CubicBezier(0.25, 0.1, 0.25, 1), "cubic-bezier(0.25, 0.1, 0.25, 1)"),
        (CubicBezier(0, 0, 1, 1), "cubic-bezier(0, 0, 1, 1)"),
        (CubicBezier(0.5, -0.5, 0.5, 1.5),
         "cubic-bezier(0.5, -0.5, 0.5, 1.5)"),
        (CubicBezier(0.1 + 0.2, 0, 0.5, 1), "cubic-bezier(0.3, 0, 0.5, 1)"),
    ],
    ids=["fractions", "integers", "negative-and-above-one", "float-noise"],
)
def test_cubic_bezier_css_is_exact(easing: Easing, expected: str) -> None:
    """Coordinates are written compactly and without floating point noise."""
    assert easing.css() == expected


def test_cubic_bezier_css_has_no_negative_zero() -> None:
    """A negative zero coordinate must be written as a plain ``0``."""
    css = CubicBezier(0.5, -0.0, 0.5, 1).css()
    assert not NEGATIVE_ZERO.search(css)


@pytest.mark.parametrize(
    ("count", "jump", "expected"),
    [
        (3, "end", "steps(3)"),
        (3, "start", "steps(3, jump-start)"),
        (3, "none", "steps(3, jump-none)"),
        (3, "both", "steps(3, jump-both)"),
        (1, "end", "steps(1)"),
    ],
)
def test_steps_css_is_exact(count: int, jump: Jump, expected: str) -> None:
    """Each jump mode maps to its CSS keyword, ``jump-end`` being implicit."""
    assert Steps(count, jump).css() == expected


def test_steps_defaults_to_jump_end() -> None:
    """Omitting ``jump`` is the same as asking for ``jump-end``."""
    assert Steps(5).css() == Steps(5, "end").css()


@each(CURVES)
def test_linear_has_a_reasonable_number_of_points(easing: Easing) -> None:
    """The curve is sampled finely enough to look smooth, yet stays compact."""
    points = linear_points(easing.css())

    assert MIN_LINEAR_POINTS <= len(points) <= MAX_LINEAR_POINTS


@each(CURVES)
def test_linear_points_are_short_decimals(easing: Easing) -> None:
    """Points use at most four decimals and no scientific notation."""
    points = linear_points(easing.css())

    assert all(LINEAR_POINT.fullmatch(point) for point in points)


@each(CURVES)
def test_linear_points_have_no_negative_zero(easing: Easing) -> None:
    """Rounding must never leave a ``-0`` point in the output."""
    points = linear_points(easing.css())

    assert not any(NEGATIVE_ZERO.fullmatch(point) for point in points)


@each(CURVES)
def test_linear_starts_at_zero_and_ends_at_one(easing: Easing) -> None:
    """The first and last points are written exactly as ``0`` and ``1``."""
    points = linear_points(easing.css())

    assert points[0] == "0"
    assert points[-1] == "1"
